                state.library.id.clone(),
                self.audiobookshelf_runtime.generation(),
            )
        };
        // Restart the catalog request from page 0 after clearing state.
        super::service_startup::start_audiobookshelf_shows(
            self.config.lock().unwrap().clone(),
