            return;
        };
        let Some(bucket) = state.buckets.get(state.selected_bucket) else {
            return;
        };
        if bucket.end <= bucket.start {
            return;
        }
        self.select_audiobookshelf_book(if end { bucket.end - 1 } else { bucket.start });
