            };
            let marker = if state.episode_selection == Some(index) {
                "> "
            } else {
                "  "
            };
            frame.render_widget(
                Paragraph::new(Line::from(vec![
                    Span::styled(marker, Style::default().fg(palette::TEXT_FOCUS_ACCENT)),
                    Span::raw(episode.title.clone()),
                ])),
